def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    s = data[0]
    t = data[1]

    prefix_s = set()
    prefix_t = set()

    for i in range(1, len(s) + 1):
        prefix_s.add(s[:i])

    for j in range(1, len(t) + 1):
        prefix_t.add(t[:j])

    distinct_strings = set()

    for ps in prefix_s:
        for pt in prefix_t:
            distinct_strings.add(ps + pt)

    print(len(distinct_strings))

if __name__ == "__main__":
    main()
